webpackJsonp([0xf6c361429d16],{457:function(e,a){e.exports={data:{site:{siteMetadata:{title:"Mihail Eric",subtitle:"Engineer, researcher, educator.",copyright:"Copyright",author:{name:"Mihail Eric",twitter:"mihail_eric"},url:"https://mihaileric.com"}},allMarkdownRemark:{edges:[{node:{fields:{slug:"/posts/state-of-the-art-question-answering-streamlit-huggingface/",tagSlugs:["/tags/natural-language-processing/","/tags/deep-learning/"]},frontmatter:{title:"Deploying a State-of-the-Art Question Answering System With 60 Lines of Python Using HuggingFace and Streamlit",tags:["Natural Language Processing","Deep Learning"],date:"2020-09-19T23:40:37.121"}}},{node:{fields:{slug:"/posts/complete-artificial-intelligence-undergraduate-course-plan/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/deep-learning/"]},frontmatter:{title:"A Complete 4-Year Course Plan for an Artificial Intelligence Undergraduate Degree",tags:["Machine Learning","A.I.","Deep Learning"],date:"2020-05-24T23:40:37.121"}}},{node:{fields:{slug:"/posts/ml-trends-neurips-2019/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/deep-learning/"]},frontmatter:{title:"Trends in Machine Learning: NeurIPS 2019 In Review",tags:["Machine Learning","A.I.","Deep Learning"],date:"2019-12-15T23:40:37.121"}}},{node:{fields:{slug:"/posts/building-a-deep-learning-computer/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/deep-learning/"]},frontmatter:{title:"The Birth of Venus: Building a Deep Learning Computer From Scratch",tags:["Machine Learning","A.I.","Deep Learning"],date:"2019-11-03T23:40:37.121"}}},{node:{fields:{slug:"/posts/ml-lesson-curriculum/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/data-science/"]},frontmatter:{title:"A Comprehensive Introduction to Machine Learning Fundamentals",tags:["Machine Learning","A.I.","Data Science"],date:"2019-09-30T23:46:37.121"}}},{node:{fields:{slug:"/posts/market-basket-analysis/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/data-science/"]},frontmatter:{title:"Market Basket Analysis",tags:["Machine Learning","A.I.","Data Science"],date:"2019-09-02T23:46:37.121"}}},{node:{fields:{slug:"/posts/decision-trees/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/data-science/"]},frontmatter:{title:"Decision Trees",tags:["Machine Learning","A.I.","Data Science"],date:"2019-09-02T23:46:37.121"}}},{node:{fields:{slug:"/posts/k-nearest-neighbors/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/data-science/"]},frontmatter:{title:"Your Closest Neighbors",tags:["Machine Learning","A.I.","Data Science"],date:"2019-08-30T23:46:37.121"}}},{node:{fields:{slug:"/posts/model-evaluation/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/data-science/"]},frontmatter:{title:"Model Evaluation",tags:["Machine Learning","A.I.","Data Science"],date:"2019-08-28T23:46:37.121"}}},{node:{fields:{slug:"/posts/machine-learning-model-selection/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/data-science/"]},frontmatter:{title:"Why Did You Choose This Model?",tags:["Machine Learning","A.I.","Data Science"],date:"2019-08-28T23:46:37.121"}}},{node:{fields:{slug:"/posts/machine-learning-ensembling/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/data-science/"]},frontmatter:{title:"Join the Ensemble",tags:["Machine Learning","A.I.","Data Science"],date:"2019-08-28T23:46:37.121"}}},{node:{fields:{slug:"/posts/regularization/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/data-science/"]},frontmatter:{title:"Model Regularization",tags:["Machine Learning","A.I.","Data Science"],date:"2019-08-25T23:46:37.121"}}},{node:{fields:{slug:"/posts/principal-components-analysis/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/data-science/"]},frontmatter:{title:"Principal Components Analysis",tags:["Machine Learning","A.I.","Data Science"],date:"2019-08-25T23:46:37.121"}}},{node:{fields:{slug:"/posts/bias-variance-tradeoff/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/data-science/"]},frontmatter:{title:"Controlling Your Model's Bias",tags:["Machine Learning","A.I.","Data Science"],date:"2019-08-25T23:46:37.121"}}},{node:{fields:{slug:"/posts/feature-selection/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/data-science/"]},frontmatter:{title:"What Features Do You Want?",tags:["Machine Learning","A.I.","Data Science"],date:"2019-08-25T23:46:37.121"}}},{node:{fields:{slug:"/posts/nlp-trends-acl-2019/",tagSlugs:["/tags/natural-language-processing/","/tags/a-i/","/tags/deep-learning/"]},frontmatter:{title:"Trends in Natural Language Processing: ACL 2019 In Review",tags:["Natural Language Processing","A.I.","Deep Learning"],date:"2019-08-03T23:40:37.121"}}},{node:{fields:{slug:"/posts/what-kmeans-clustering/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/data-science/"]},frontmatter:{title:"What K-Means",tags:["Machine Learning","A.I.","Data Science"],date:"2019-07-16T23:46:37.121"}}},{node:{fields:{slug:"/posts/recurrent-neural-networks/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/deep-learning/"]},frontmatter:{title:"Recurrent Neural Networks",tags:["Machine Learning","A.I.","Deep Learning"],date:"2019-05-03T23:46:37.121"}}},{node:{fields:{slug:"/posts/convolutional-neural-networks/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/deep-learning/"]},frontmatter:{title:"Dance Dance Convolution",tags:["Machine Learning","A.I.","Deep Learning"],date:"2019-05-03T23:40:37.121"}}},{node:{fields:{slug:"/posts/neural-network-grab-bag/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/deep-learning/"]},frontmatter:{title:"Neural Network Grab Bag",tags:["Machine Learning","A.I.","Deep Learning"],date:"2019-05-03T22:46:37.121"}}},{node:{fields:{slug:"/posts/deep-dive-into-neural-networks/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/deep-learning/"]},frontmatter:{title:"Deep Dive Into Neural Networks",tags:["Machine Learning","A.I.","Deep Learning"],date:"2019-04-28T23:46:37.121"}}},{node:{fields:{slug:"/posts/support-vector-machines/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/data-science/"]},frontmatter:{title:"Basics of Support Vector Machines",tags:["Machine Learning","A.I.","Data Science"],date:"2019-04-20T23:46:37.121"}}},{node:{fields:{slug:"/posts/not-so-naive-bayes/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/data-science/"]},frontmatter:{title:"Why So Naive, Bayes?",tags:["Machine Learning","A.I.","Data Science"],date:"2019-04-13T23:46:37.121"}}},{node:{fields:{slug:"/posts/introduction-to-logistic-regression/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/data-science/"]},frontmatter:{title:"Introduction to Logistic Regression",tags:["Machine Learning","A.I.","Data Science"],date:"2019-04-08T23:46:37.121"}}},{node:{fields:{slug:"/posts/fundamentals-of-linear-regression/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/data-science/"]},frontmatter:{title:"Fundamentals of Linear Regression",tags:["Machine Learning","A.I.","Data Science"],date:"2019-03-15T23:46:37.121"}}},{node:{fields:{slug:"/posts/transformers-attention-in-disguise/",tagSlugs:["/tags/a-i/","/tags/natural-language-processing/","/tags/deep-learning/"]},frontmatter:{title:"Transformers: Attention in Disguise",tags:["A.I.","Natural Language Processing","Deep Learning"],date:"2018-10-22T23:46:37.121"}}},{node:{fields:{slug:"/posts/deep-contextualized-word-representations-elmo/",tagSlugs:["/tags/a-i/","/tags/natural-language-processing/","/tags/deep-learning/"]},frontmatter:{title:"Deep Contextualized Word Representations with ELMo",tags:["A.I.","Natural Language Processing","Deep Learning"],date:"2018-10-08T23:46:37.121"}}},{node:{fields:{slug:"/posts/fast-object-detection-with-fast-rcnn/",tagSlugs:["/tags/machine-learning/","/tags/computer-vision/","/tags/deep-learning/"]},frontmatter:{title:"Fast Object Detection with Fast R-CNN",tags:["Machine Learning","Computer Vision","Deep Learning"],date:"2018-10-01T23:46:37.121"}}},{node:{fields:{slug:"/posts/object-detection-with-rcnn/",tagSlugs:["/tags/machine-learning/","/tags/computer-vision/","/tags/deep-learning/"]},frontmatter:{title:"Object Detection with R-CNN",tags:["Machine Learning","Computer Vision","Deep Learning"],date:"2018-10-01T23:46:37.121"}}},{node:{fields:{slug:"/posts/fundamental-deep-learning-algorithms-to-learn/",tagSlugs:["/tags/a-i/","/tags/deep-learning/","/tags/machine-learning/"]},frontmatter:{title:"Fundamental Deep Learning Algorithms To Learn",tags:["A.I.","Deep Learning","Machine Learning"],date:"2018-08-14T23:46:37.121"}}},{node:{fields:{slug:"/posts/why-all-the-excitement-about-ai/",tagSlugs:["/tags/a-i/","/tags/machine-learning/","/tags/deep-learning/"]},frontmatter:{title:"Why All The Excitement About Artificial Intelligence",tags:["A.I.","Machine Learning","Deep Learning"],date:"2018-08-14T23:46:37.121"}}},{node:{fields:{slug:"/posts/being-a-good-machine-learning-data-scientist/",tagSlugs:["/tags/a-i/","/tags/data-science/","/tags/machine-learning/"]},frontmatter:{title:"Being a Good Machine Learning Engineer/Data Scientist",tags:["A.I.","Data Science","Machine Learning"],date:"2018-08-11T23:46:37.121"}}},{node:{fields:{slug:"/posts/a-software-interview-challenge/",tagSlugs:["/tags/software-engineering/","/tags/interview-prep/"]},frontmatter:{title:"A Software Interview Challenge",tags:["Software Engineering","Interview Prep"],date:"2017-12-24T23:46:37.121"}}},{node:{fields:{slug:"/posts/review-of-sigdial-semdial-2017/",tagSlugs:["/tags/natural-language-processing/","/tags/a-i/","/tags/deep-learning/"]},frontmatter:{title:"Review of SIGDial/SemDial 2017",tags:["Natural Language Processing","A.I.","Deep Learning"],date:"2017-09-04T23:46:37.121"}}},{node:{fields:{slug:"/posts/a-new-multiturn-dialogue-dataset/",tagSlugs:["/tags/natural-language-processing/","/tags/dataset/","/tags/dialogue/"]},frontmatter:{title:"A New Multi-Turn, Multi-Domain, Task-Oriented Dialogue Dataset",tags:["Natural Language Processing","Dataset","Dialogue"],date:"2017-07-03T23:46:37.121"}}}]},markdownRemark:{id:"/Users/mihaileric/Documents/Projects/mihail911.github.io/src/pages/articles/2018-29-09---Object-Detection-With-RCNN/index.md absPath of file >>> MarkdownRemark",html:'<p>\n  <a\n    class="gatsby-resp-image-link"\n    href="/static/dog_with_ball-db327d9f059c1de766b4eaa6acb2039b-f3e7c.png"\n    style="display: block"\n    target="_blank"\n    rel="noopener"\n  >\n  \n  <span\n    class="gatsby-resp-image-wrapper"\n    style="position: relative; display: block; ; max-width: 748px; margin-left: auto; margin-right: auto;"\n  >\n    <span\n      class="gatsby-resp-image-background-image"\n      style="padding-bottom: 75.1336898395722%; position: relative; bottom: 0; left: 0; background-image: url(\'data:image/png;base64,\'); background-size: cover; display: block;"\n    >\n      <img\n        class="gatsby-resp-image-image"\n        style="width: 100%; height: 100%; margin: 0; vertical-align: middle; position: absolute; top: 0; left: 0; box-shadow: inset 0px 0px 0px 400px white;"\n        alt="Region proposals with convolutional neural networks dog with ball object detection "\n        title=""\n        src="/static/dog_with_ball-db327d9f059c1de766b4eaa6acb2039b-f3e7c.png"\n        srcset="/static/dog_with_ball-db327d9f059c1de766b4eaa6acb2039b-388be.png 240w,\n/static/dog_with_ball-db327d9f059c1de766b4eaa6acb2039b-726d8.png 480w,\n/static/dog_with_ball-db327d9f059c1de766b4eaa6acb2039b-f3e7c.png 748w"\n        sizes="(max-width: 748px) 100vw, 748px"\n      />\n    </span>\n  </span>\n  \n  </a>\n    </p>\n<p>In this post, I want to discuss one of the seminal object detection architectures of the last decade: <strong>region proposals with convolutional neural networks</strong>\n(or R-CNN for short). R-CNN is one of the earliest models that piggybacked\noff the computer vision deep learning revolution begun with the advent of <a href="https://en.wikipedia.org/wiki/AlexNet">AlexNet</a>.</p>\n<p>When it was released, R-CNN completely trounced the existing state-of-the-art in object detection. Though it has since been\nreplaced by more powerful algorithms, the R-CNN paper still fundamentally changed the way in which people think about object\ndetection and its symbiotic relationship with deep learning. </p>\n<p>There is a lot to unpack in the <a href="https://arxiv.org/abs/1311.2524">R-CNN paper</a>, as the authors did a fantastic job of meticulously evaluating their model, running\nablation studies, making appropriate visualizations, etc. I am going to distill the paper’s contents to what I believe are the most\nsalient kernels of insight. But I recognize we are all busy people 😉, so for those that want a super abbreviated\nversion, here’s a TLDR of the paper:</p>\n<ol>\n<li><strong>Supervised pretraining using external data followed by domain-specific fine-tuning makes a huge difference with model performance</strong>  </li>\n<li><strong>Using convolutional networks to extract powerful feature representations from images changes the game in object detection</strong></li>\n</ol>\n<p>… And for those that want a longer version, read onward! </p>\n<h2>How R-CNN Works</h2>\n<p>R-CNN is a sophisticated system with a lot of moving parts, so let’s start our analysis of it at the end.\nWhen all is said and done, what does the final system actually look like?</p>\n<p>As a motivating example, let’s say we wanted to run an R-CNN object detection on the following image: </p>\n<p>\n  <a\n    class="gatsby-resp-image-link"\n    href="/static/cat_and_dog-d1ca74c7b503381e4b6e6ae117d36e08-a560a.png"\n    style="display: block"\n    target="_blank"\n    rel="noopener"\n  >\n  \n  <span\n    class="gatsby-resp-image-wrapper"\n    style="position: relative; display: block; ; max-width: 960px; margin-left: auto; margin-right: auto;"\n  >\n    <span\n      class="gatsby-resp-image-background-image"\n      style="padding-bottom: 56.21621621621622%; position: relative; bottom: 0; left: 0; background-image: url(\'data:image/png;base64,\'); background-size: cover; display: block;"\n    >\n      <img\n        class="gatsby-resp-image-image"\n        style="width: 100%; height: 100%; margin: 0; vertical-align: middle; position: absolute; top: 0; left: 0; box-shadow: inset 0px 0px 0px 400px white;"\n        alt="Cat with dog starting image for object detection for r-cnn"\n        title=""\n        src="/static/cat_and_dog-d1ca74c7b503381e4b6e6ae117d36e08-3d61e.png"\n        srcset="/static/cat_and_dog-d1ca74c7b503381e4b6e6ae117d36e08-d182c.png 240w,\n/static/cat_and_dog-d1ca74c7b503381e4b6e6ae117d36e08-5220f.png 480w,\n/static/cat_and_dog-d1ca74c7b503381e4b6e6ae117d36e08-3d61e.png 960w,\n/static/cat_and_dog-d1ca74c7b503381e4b6e6ae117d36e08-a560a.png 1110w"\n        sizes="(max-width: 960px) 100vw, 960px"\n      />\n    </span>\n  </span>\n  \n  </a>\n    </p>\n<p>Adorable, I know. The first step of the process involves extracting <em>region proposals</em> from the image, which\nare essentially smaller subimages that could potentially contain an object. There are a number of algorithms that can\nbe used to generate region proposals, though the one that R-CNN uses is called <a href="http://www.huppelen.nl/publications/selectiveSearchDraft.pdf"><em>selective search</em></a>. This algorithm\niteratively combines subimages in a bottom-up fashion, using various image similarity metrics such as color and texture. </p>\n<p>R-CNN extracts around 2000 region proposals per image, which would look as follows:</p>\n<p>\n  <a\n    class="gatsby-resp-image-link"\n    href="/static/cat_and_dog_region_proposals-9da6a68b2f9d8aa09f9cb0497cbd4678-d13b4.png"\n    style="display: block"\n    target="_blank"\n    rel="noopener"\n  >\n  \n  <span\n    class="gatsby-resp-image-wrapper"\n    style="position: relative; display: block; ; max-width: 960px; margin-left: auto; margin-right: auto;"\n  >\n    <span\n      class="gatsby-resp-image-background-image"\n      style="padding-bottom: 55.77617328519856%; position: relative; bottom: 0; left: 0; background-image: url(\'data:image/png;base64,\'); background-size: cover; display: block;"\n    >\n      <img\n        class="gatsby-resp-image-image"\n        style="width: 100%; height: 100%; margin: 0; vertical-align: middle; position: absolute; top: 0; left: 0; box-shadow: inset 0px 0px 0px 400px white;"\n        alt="Cat with dog object detection with region proposals for r-cnn"\n        title=""\n        src="/static/cat_and_dog_region_proposals-9da6a68b2f9d8aa09f9cb0497cbd4678-3d61e.png"\n        srcset="/static/cat_and_dog_region_proposals-9da6a68b2f9d8aa09f9cb0497cbd4678-d182c.png 240w,\n/static/cat_and_dog_region_proposals-9da6a68b2f9d8aa09f9cb0497cbd4678-5220f.png 480w,\n/static/cat_and_dog_region_proposals-9da6a68b2f9d8aa09f9cb0497cbd4678-3d61e.png 960w,\n/static/cat_and_dog_region_proposals-9da6a68b2f9d8aa09f9cb0497cbd4678-d13b4.png 1108w"\n        sizes="(max-width: 960px) 100vw, 960px"\n      />\n    </span>\n  </span>\n  \n  </a>\n    </p>\n<p>Now R-CNN runs each proposal through a high-capacity <a href="https://en.wikipedia.org/wiki/Convolutional_neural_network">convolutional neural network</a> to extract a learned\nfeature representation, which ideally holds meaningful information about the objects in the image. </p>\n<p>For example, the algorithm would take a proposal such as the following:</p>\n<p>\n  <a\n    class="gatsby-resp-image-link"\n    href="/static/cat_and_dog_single_region_proposal-373293157e3ee3fe74e3ab3a4f1fd234-cb1cf.png"\n    style="display: block"\n    target="_blank"\n    rel="noopener"\n  >\n  \n  <span\n    class="gatsby-resp-image-wrapper"\n    style="position: relative; display: block; ; max-width: 960px; margin-left: auto; margin-right: auto;"\n  >\n    <span\n      class="gatsby-resp-image-background-image"\n      style="padding-bottom: 55.75539568345324%; position: relative; bottom: 0; left: 0; background-image: url(\'data:image/png;base64,\'); background-size: cover; display: block;"\n    >\n      <img\n        class="gatsby-resp-image-image"\n        style="width: 100%; height: 100%; margin: 0; vertical-align: middle; position: absolute; top: 0; left: 0; box-shadow: inset 0px 0px 0px 400px white;"\n        alt="Cat with dog object detection with single region proposal for r-cnn"\n        title=""\n        src="/static/cat_and_dog_single_region_proposal-373293157e3ee3fe74e3ab3a4f1fd234-3d61e.png"\n        srcset="/static/cat_and_dog_single_region_proposal-373293157e3ee3fe74e3ab3a4f1fd234-d182c.png 240w,\n/static/cat_and_dog_single_region_proposal-373293157e3ee3fe74e3ab3a4f1fd234-5220f.png 480w,\n/static/cat_and_dog_single_region_proposal-373293157e3ee3fe74e3ab3a4f1fd234-3d61e.png 960w,\n/static/cat_and_dog_single_region_proposal-373293157e3ee3fe74e3ab3a4f1fd234-cb1cf.png 1112w"\n        sizes="(max-width: 960px) 100vw, 960px"\n      />\n    </span>\n  </span>\n  \n  </a>\n    </p>\n<p>This proposal would be forward-propagated through a convolutional neural network to generate a 4096-dimensional feature\nvector:</p>\n<p>\n  <a\n    class="gatsby-resp-image-link"\n    href="/static/region_proposal_through_convolutional_network-febb271944965e81e21ee84813f1184e-4c80f.png"\n    style="display: block"\n    target="_blank"\n    rel="noopener"\n  >\n  \n  <span\n    class="gatsby-resp-image-wrapper"\n    style="position: relative; display: block; ; max-width: 960px; margin-left: auto; margin-right: auto;"\n  >\n    <span\n      class="gatsby-resp-image-background-image"\n      style="padding-bottom: 64.38529784537388%; position: relative; bottom: 0; left: 0; background-image: url(\'data:image/png;base64,\'); background-size: cover; display: block;"\n    >\n      <img\n        class="gatsby-resp-image-image"\n        style="width: 100%; height: 100%; margin: 0; vertical-align: middle; position: absolute; top: 0; left: 0; box-shadow: inset 0px 0px 0px 400px white;"\n        alt="Region proposal through convolutional neural network"\n        title=""\n        src="/static/region_proposal_through_convolutional_network-febb271944965e81e21ee84813f1184e-3d61e.png"\n        srcset="/static/region_proposal_through_convolutional_network-febb271944965e81e21ee84813f1184e-d182c.png 240w,\n/static/region_proposal_through_convolutional_network-febb271944965e81e21ee84813f1184e-5220f.png 480w,\n/static/region_proposal_through_convolutional_network-febb271944965e81e21ee84813f1184e-3d61e.png 960w,\n/static/region_proposal_through_convolutional_network-febb271944965e81e21ee84813f1184e-6fd10.png 1440w,\n/static/region_proposal_through_convolutional_network-febb271944965e81e21ee84813f1184e-4c80f.png 1578w"\n        sizes="(max-width: 960px) 100vw, 960px"\n      />\n    </span>\n  </span>\n  \n  </a>\n    </p>\n<p>Afterwards, this feature vector is run through a collection of linear support vector machines (SVM for short), where each SVM\nis designed to classify for a single object class. In other words, there is an SVM trained to detect <em>boat</em>, another\none for <em>parrot</em>, etc. </p>\n<p>Each SVM outputs a score for the given class, indicating the likelihood that the region proposal\ncontains that class. Note, that the exact classes that can be identified depend on the dataset used for training.</p>\n<p>This step of the process looks as follows: </p>\n<p>\n  <a\n    class="gatsby-resp-image-link"\n    href="/static/vector_through_svm_classifiers-cc139d6728db3205c0297a8f04c010ee-90f45.png"\n    style="display: block"\n    target="_blank"\n    rel="noopener"\n  >\n  \n  <span\n    class="gatsby-resp-image-wrapper"\n    style="position: relative; display: block; ; max-width: 960px; margin-left: auto; margin-right: auto;"\n  >\n    <span\n      class="gatsby-resp-image-background-image"\n      style="padding-bottom: 50.38265306122449%; position: relative; bottom: 0; left: 0; background-image: url(\'data:image/png;base64,\'); background-size: cover; display: block;"\n    >\n      <img\n        class="gatsby-resp-image-image"\n        style="width: 100%; height: 100%; margin: 0; vertical-align: middle; position: absolute; top: 0; left: 0; box-shadow: inset 0px 0px 0px 400px white;"\n        alt="support vector machine classifiers per class for object detection"\n        title=""\n        src="/static/vector_through_svm_classifiers-cc139d6728db3205c0297a8f04c010ee-3d61e.png"\n        srcset="/static/vector_through_svm_classifiers-cc139d6728db3205c0297a8f04c010ee-d182c.png 240w,\n/static/vector_through_svm_classifiers-cc139d6728db3205c0297a8f04c010ee-5220f.png 480w,\n/static/vector_through_svm_classifiers-cc139d6728db3205c0297a8f04c010ee-3d61e.png 960w,\n/static/vector_through_svm_classifiers-cc139d6728db3205c0297a8f04c010ee-6fd10.png 1440w,\n/static/vector_through_svm_classifiers-cc139d6728db3205c0297a8f04c010ee-90f45.png 1568w"\n        sizes="(max-width: 960px) 100vw, 960px"\n      />\n    </span>\n  </span>\n  \n  </a>\n    </p>\n<p>R-CNN will then label the region proposal with the class corresponding to the highest-scoring SVM, in this case\n<em>dog</em>. </p>\n<p>After R-CNN has scored each region proposal with a class-specific SVM, the bounding box for the proposal is refined\nusing a class-specific bounding-box regressor. This could adjust the region in the following way:</p>\n<p>\n  <a\n    class="gatsby-resp-image-link"\n    href="/static/bounding_box_regressor-d8584173ba8e116ced1aa45323a79b44-dba13.png"\n    style="display: block"\n    target="_blank"\n    rel="noopener"\n  >\n  \n  <span\n    class="gatsby-resp-image-wrapper"\n    style="position: relative; display: block; ; max-width: 960px; margin-left: auto; margin-right: auto;"\n  >\n    <span\n      class="gatsby-resp-image-background-image"\n      style="padding-bottom: 67.91147994467497%; position: relative; bottom: 0; left: 0; background-image: url(\'data:image/png;base64,\'); background-size: cover; display: block;"\n    >\n      <img\n        class="gatsby-resp-image-image"\n        style="width: 100%; height: 100%; margin: 0; vertical-align: middle; position: absolute; top: 0; left: 0; box-shadow: inset 0px 0px 0px 400px white;"\n        alt="class specific bounding box regressor for dog"\n        title=""\n        src="/static/bounding_box_regressor-d8584173ba8e116ced1aa45323a79b44-3d61e.png"\n        srcset="/static/bounding_box_regressor-d8584173ba8e116ced1aa45323a79b44-d182c.png 240w,\n/static/bounding_box_regressor-d8584173ba8e116ced1aa45323a79b44-5220f.png 480w,\n/static/bounding_box_regressor-d8584173ba8e116ced1aa45323a79b44-3d61e.png 960w,\n/static/bounding_box_regressor-d8584173ba8e116ced1aa45323a79b44-6fd10.png 1440w,\n/static/bounding_box_regressor-d8584173ba8e116ced1aa45323a79b44-dba13.png 1446w"\n        sizes="(max-width: 960px) 100vw, 960px"\n      />\n    </span>\n  </span>\n  \n  </a>\n    </p>\n<p>When the process is finished, the detected object for the region could look as follows:</p>\n<p>\n  <a\n    class="gatsby-resp-image-link"\n    href="/static/scored_dog_region_proposal-0528a87ac19d57d3af61cf7e7fca4ce1-d90da.png"\n    style="display: block"\n    target="_blank"\n    rel="noopener"\n  >\n  \n  <span\n    class="gatsby-resp-image-wrapper"\n    style="position: relative; display: block; ; max-width: 960px; margin-left: auto; margin-right: auto;"\n  >\n    <span\n      class="gatsby-resp-image-background-image"\n      style="padding-bottom: 42.840095465393794%; position: relative; bottom: 0; left: 0; background-image: url(\'data:image/png;base64,\'); background-size: cover; display: block;"\n    >\n      <img\n        class="gatsby-resp-image-image"\n        style="width: 100%; height: 100%; margin: 0; vertical-align: middle; position: absolute; top: 0; left: 0; box-shadow: inset 0px 0px 0px 400px white;"\n        alt="scored dog region proposal for object detection"\n        title=""\n        src="/static/scored_dog_region_proposal-0528a87ac19d57d3af61cf7e7fca4ce1-3d61e.png"\n        srcset="/static/scored_dog_region_proposal-0528a87ac19d57d3af61cf7e7fca4ce1-d182c.png 240w,\n/static/scored_dog_region_proposal-0528a87ac19d57d3af61cf7e7fca4ce1-5220f.png 480w,\n/static/scored_dog_region_proposal-0528a87ac19d57d3af61cf7e7fca4ce1-3d61e.png 960w,\n/static/scored_dog_region_proposal-0528a87ac19d57d3af61cf7e7fca4ce1-6fd10.png 1440w,\n/static/scored_dog_region_proposal-0528a87ac19d57d3af61cf7e7fca4ce1-d90da.png 1676w"\n        sizes="(max-width: 960px) 100vw, 960px"\n      />\n    </span>\n  </span>\n  \n  </a>\n    </p>\n<p>Note, this running example was only for a single region proposal. Running the algorithm on the other\nregions should detect that there is also a cat in the image. </p>\n<p>With all that, we have completed an execution of R-CNN!</p>\n<h2>How R-CNN is Built</h2>\n<p>The running example from the last section showed us what it looks like when we have a trained, fresh-out-of-the-oven\nR-CNN to detect objects with. But how do we actually get to a fully-fledged system? </p>\n<p>We will first focus on details regarding the convolutional neural network step of the R-CNN pipeline. The CNN used\nfor the model is <a href="https://papers.nips.cc/paper/4824-imagenet-classification-with-deep-convolutional-neural-networks.pdf">AlexNet</a>,\na standard deep CNN with five convolutional layers and two fully-connected layers.</p>\n<figure>\n\t\n  <a class="gatsby-resp-image-link" href="/static/alexnet-2d0de2a234a9e17c084b48657a3e48fa-1e6b8.png" style="display: block" target="_blank" rel="noopener">\n  \n  <span class="gatsby-resp-image-wrapper" style="position: relative; display: block; ; max-width: 960px; margin-left: auto; margin-right: auto;">\n    <span class="gatsby-resp-image-background-image" style="padding-bottom: 31.803962460896766%; position: relative; bottom: 0; left: 0; background-image: url(&apos;data:image/png;base64,&apos;); background-size: cover; display: block;">\n      <img class="gatsby-resp-image-image" style="width: 100%; height: 100%; margin: 0; vertical-align: middle; position: absolute; top: 0; left: 0; box-shadow: inset 0px 0px 0px 400px white;" alt="The AlexNet convolutional neural network architecture" title="" src="/static/alexnet-2d0de2a234a9e17c084b48657a3e48fa-3d61e.png" srcset="/static/alexnet-2d0de2a234a9e17c084b48657a3e48fa-d182c.png 240w,\n/static/alexnet-2d0de2a234a9e17c084b48657a3e48fa-5220f.png 480w,\n/static/alexnet-2d0de2a234a9e17c084b48657a3e48fa-3d61e.png 960w,\n/static/alexnet-2d0de2a234a9e17c084b48657a3e48fa-6fd10.png 1440w,\n/static/alexnet-2d0de2a234a9e17c084b48657a3e48fa-1e6b8.png 1918w" sizes="(max-width: 960px) 100vw, 960px">\n    </span>\n  </span>\n  \n  </a>\n    \n\t<figcaption>AlexNet architecture diagram, taken from the original paper</figcaption>\n</figure>\n<p>One of R-CNN’s biggest contributions is the use of <em>supervised pre-training</em> for object detection. When building the CNN\ncomponent, we first train it on a large auxiliary dataset such as the <a href="http://image-net.org/challenges/LSVRC/2012/">ILSVRC 2012 classification dataset</a>. </p>\n<p>Note, that this\ndataset only contains <em>image-level labels</em>. In other words, the CNN is trained as if it is being used as a pure object\nclassifier rather than an object detector. The CNN is trained to the point where it is within a few percentage points of\nthe top-scoring performance of AlexNet. </p>\n<p>After this is done, we fine-tune the CNN parameters, using a domain-specific dataset. For the purposes of R-CNN object\ndetection, either the <a href="http://host.robots.ox.ac.uk/pascal/VOC/">PASCAL VOC dataset</a> or the <a href="http://image-net.org/challenges/LSVRC/2013/">ILSVRC 2013 detection dataset</a> is used\nto further tune the CNN parameters.</p>\n<p>Practically speaking, the 1000-way classification\nlayer of a typical AlexNet (for the 1000 classes in the ILSVRC 2012 dataset) is replaced with an (<em>N</em>+1)-way classification,\nwhere <em>N</em> is the number of object classes in the new dataset being used and an extra class is added for the <em>background</em>\nlabel. <em>N</em> is 20 in the case of VOC and 200 in the case of ILSVRC 2013.</p>\n<p>The CNN is then trained further using these domain-specific datasets. Each region proposal is considered a positive for the\nclass with which it has an <a href="https://www.pyimagesearch.com/2016/11/07/intersection-over-union-iou-for-object-detection/">intersection-over-union</a> (IoU) of at least 0.5 with a ground-truth bounding box from the dataset. </p>\n<p>Next, the training of the linear SVM classifiers also employs the domain-specific dataset. However, in this case the definition of\na positive/negative example is slightly different from the definition for the CNN training. In particular, a positive example is simply one of the ground-truth\nbounding boxes for a given class, whereas a negative example is a region proposal which has an IoU of\nless than 0.3. In the original paper, these IoU thresholds were determined empirically, and picking them carefully turned out to have quite a difference\non R-CNN’s performance.  </p>\n<p>Finally, the bounding box regressors were built using regularized least squares regressors and a dataset of (<em>P</em>, <em>G</em>) pairs, where\n<em>P</em> is a region proposal and <em>G</em> is a ground-truth bounding box. </p>\n<p>An important detail in this stage of training is how we determine\nwhich ground-truth box maps appropriately to a given proposal, as this drastically affects how feasible the learning problem is.\nThis entails a meaningful definition of <em>nearness</em>. For the purposes of R-CNN, a proposal <em>P</em> is assigned to the <em>G</em> with\nwhich it has maximal IoU overlap, as long as that overlap exceeds some empirically-determined threshold (0.6 in the case of the original R-CNN). </p>\n<p>These are all the training phases of R-CNN. It is worth noting that training the entire system is actually quite complex. There are effectively three separate steps of the\ntraining process that require data:</p>\n<ul>\n<li>CNN fine-tuning</li>\n<li>SVM classifier training</li>\n<li>Bounding box regressor training</li>\n</ul>\n<h2>Experiments</h2>\n<p>When R-CNN first was proposed, it was a state-of-the-art object detector on a number of standard datasets, so it is worth mentioning\nsome of the model’s achievements. </p>\n<p>The R-CNN architecture achieved a <a href="https://medium.com/@jonathan_hui/map-mean-average-precision-for-object-detection-45c121a31173">mean average precision</a> (mAP) score\nof 53.3% on the VOC 2012 dataset, which was an increase of <strong>more than 30% over the previous best</strong>. That is absolutely crazy!</p>\n<p>In addition, the architecture achieved a mAP of 31.4% on the ILSVRC 2013 competition, substantially ahead of the second-best score of 24.3%.</p>\n<p>What’s also worth noting is the difference doing supervised pretraining with domain-specific fine-tuning made in terms of performance. This\ndesign decision was tested in the context of the VOC 2007 dataset, and it resulted in an increase of 8.0 mAP percentage points!</p>\n<p>Finally, comparing R-CNN to pure feature-based models indicated that R-CNN achieves a mAP that is more than 20% higher on PASCAL VOC. </p>\n<h2>Final Thoughts</h2>\n<p>R-CNN fundamentally changed the landscape of object detection at the time of its conception, and it has radically influenced\nthe design of modern-day detection algorithms. </p>\n<p>In spite of that, one of the major shortcomings of R-CNN was the speed\nwith which it worked. For example, as the original paper noted, simply computing region proposals and features would take <em>13 seconds per image on a GPU.</em>\nThis is clearly too slow for a real-time object detection algorithm. </p>\n<p>Follow-up work sought to reduce the runtime of the model, especially time spent on computing region proposals. We will discuss\nthese improved algorithms including Fast R-CNN, Faster R-CNN, and YOLO in subsequent blog posts. </p>\n<p>In the meantime, if you are interested in further checking out some of R-CNN’s implementation details, you can <a href="https://github.com/rbgirshick/rcnn">see the original repo</a>.</p>',
fields:{tagSlugs:["/tags/machine-learning/","/tags/computer-vision/","/tags/deep-learning/"]},frontmatter:{title:"Object Detection with R-CNN",tags:["Machine Learning","Computer Vision","Deep Learning"],date:"2018-10-01T23:46:37.121",description:"A discussion of R-CNN, a historic object detection architecture combining region proposals with convolutional neural networks."}}},pathContext:{slug:"/posts/object-detection-with-rcnn/"}}}});
//# sourceMappingURL=path---posts-object-detection-with-rcnn-2005350d4c3bea268c07.js.map